'use strict';
const WORDS='require provide improve avoid remain likely concern benefit reduce evidence despite affect lack assume maintain contribute approach significant account decline'.split(' ');
const STORAGE='cet6-vocabulary-01-v1';
const $=id=>document.getElementById(id);
let data={version:1,test:'cet6-vocabulary-01',status:'active',createdAt:new Date().toISOString(),responses:WORDS.map((word,i)=>({number:i+1,word,meaning:'',confidence:''}))};
try{const old=JSON.parse(localStorage.getItem(STORAGE));if(old?.test===data.test&&old.responses?.length===20&&old.responses.every((r,i)=>r.word===WORDS[i]))data=old;}catch{}
const completed=r=>r.confidence==='unknown'||r.confidence==='familiar'||(r.confidence==='known'&&r.meaning.trim().length>0);
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(data));$('saveStatus').textContent='已自动保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});}catch{$('vnotice').textContent='当前浏览器无法保存，请及时导出答卷备份。';}}
function update(){const n=data.responses.filter(completed).length;$('progressLabel').textContent=n+' / 20 已完成';$('progress').value=n;data.responses.forEach((r,i)=>$('word-'+i).classList.toggle('filled',completed(r)));}
function render(){const list=$('words');list.replaceChildren();data.responses.forEach((r,i)=>{const row=document.createElement('div');row.className='vrow';row.id='word-'+i;row.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><strong>${WORDS[i]}</strong><input type="text" aria-label="${WORDS[i]}的中文意思" placeholder="写一个中文意思；不会可留空" autocomplete="off" spellcheck="false"><select aria-label="${WORDS[i]}的熟悉程度"><option value="">选择熟悉程度</option><option value="known">有把握</option><option value="familiar">眼熟</option><option value="unknown">不会</option></select><div class="definition" hidden></div>`;const input=row.querySelector('input'),select=row.querySelector('select');input.value=r.meaning;select.value=r.confidence;input.disabled=select.disabled=data.status==='submitted';input.oninput=()=>{if(data.status==='submitted')return;r.meaning=input.value;save();update();};select.onchange=()=>{if(data.status==='submitted')return;r.confidence=select.value;save();update();};list.append(row);});update();if(data.status==='submitted')showReview();}
function goToMissing(){const i=data.responses.findIndex(r=>!completed(r));if(i<0)return;const row=$('word-'+i);row.scrollIntoView({behavior:'smooth',block:'center'});(data.responses[i].confidence==='known'?row.querySelector('input'):row.querySelector('select')).focus({preventScroll:true});}
function exportAnswers(){const out={...data,exportedAt:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='CET6-词汇摸底01-'+new Date().toLocaleDateString('sv-SE')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function showReview(){window.dispatchEvent(new Event("vocabulary-submitted"));const counts={known:0,familiar:0,unknown:0};data.responses.forEach(r=>counts[r.confidence]++);$('summary').hidden=false;$('trainingActions').hidden=false;$('summary').textContent=`本轮已提交：自评有把握 ${counts.known} 词，眼熟 ${counts.familiar} 词，不会 ${counts.unknown} 词。这是自评数量，尚未判定对错。请导出答卷发回聊天。`;$('submit').hidden=true;$('jump').hidden=true;try{const res=await fetch('vocabulary-key.json');if(!res.ok)throw Error('释义未能加载');const key=await res.json();data.responses.forEach((r,i)=>{const div=$('word-'+i).querySelector('.definition');div.hidden=false;div.textContent='参考释义：'+key[r.word];});$('vnotice').textContent='';}catch{$('vnotice').textContent='参考释义暂未加载成功。答卷已保存，可刷新重试或直接导出。';}}
$('export').onclick=$('exportBottom').onclick=exportAnswers;$('jump').onclick=goToMissing;
$('submit').onclick=()=>{if(!data.responses.every(completed)){$('vnotice').textContent='请先给每个词选择熟悉程度；选择“有把握”的词需要填写意思。';goToMissing();return;}$('confirm').showModal();};
$('cancel').onclick=()=>$('confirm').close();$('confirmSubmit').onclick=()=>{if(data.status==='submitted')return;data.status='submitted';data.submittedAt=new Date().toISOString();save();$('confirm').close();render();$('summary').scrollIntoView({behavior:'smooth',block:'center'});};
render();
